-- Test-only PostgreSQL equivalent of db/migrations/003_club_applications.sql
ALTER TABLE clubs ADD COLUMN key_contact_name varchar(160), ADD COLUMN key_contact_detail varchar(190), ADD COLUMN submitted_at timestamptz, ADD COLUMN safeguarding_confirmed_at timestamptz, ADD COLUMN safeguarding_confirmed_by varchar(160), ADD COLUMN approved_at timestamptz, ADD COLUMN approved_by_user_id bigint;
ALTER TABLE coaches ADD COLUMN dbs_method varchar(20), ADD COLUMN dbs_confirmed_by varchar(160), ADD COLUMN is_safeguarding_officer boolean NOT NULL DEFAULT false;
CREATE TABLE verification_tokens (id bigserial PRIMARY KEY, club_id bigint NOT NULL REFERENCES clubs(id) ON DELETE CASCADE, token_hash char(64) NOT NULL UNIQUE, role varchar(10) NOT NULL CHECK (role IN ('officer','second')), person_name varchar(160) NOT NULL, sent_to varchar(190) NOT NULL, coach_ids varchar(200), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, reminded_at timestamptz, last_used_at timestamptz);
CREATE TABLE dbs_confirmations (id bigserial PRIMARY KEY, coach_id bigint NOT NULL REFERENCES coaches(id) ON DELETE CASCADE, token_id bigint, confirmed_by varchar(160) NOT NULL, confirmed_by_email varchar(190), method varchar(20) NOT NULL CHECK (method IN ('certificate','update_service','by_hand')), checked_on date NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
